with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الديناميكا الجوية والفيزياء الجوية والتنبؤ العددي','الديناميكا الحرارية والاستقرار والسحب والأنظمة الجوية ومبادئ التنبؤ العددي والتحقق منه.',13,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الحرارة والرطوبة والتحولات الأديباتية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'السحب والهطول والأنظمة الجوية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'أساسيات التنبؤ العددي',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تصميم وتشغيل النماذج',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u5 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تقييم التنبؤ وعدم اليقين',5,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('atmospheric-thermodynamics','الديناميكا الحرارية للغلاف الجوي','قوانين الطاقة والحرارة النوعية والتحولات الأديباتية في الهواء.','{"blocks":[{"type":"text","text":"تدرس الديناميكا الحرارية الجوية تبادل الطاقة وتحولاتها في الهواء، وتفسر تغير درجة الحرارة والرطوبة والكثافة أثناء الحركة الرأسية."},{"type":"text","text":"تصف درجة الحرارة الحالة الحرارية للهواء، بينما تعبر الحرارة عن انتقال الطاقة بسبب فرق درجة الحرارة؛ وهما مفهومان مختلفان."},{"type":"text","text":"تحدد السعة الحرارية النوعية مقدار الطاقة اللازمة لتغيير درجة حرارة وحدة الكتلة درجة واحدة، وتدخل في تقدير استجابة الهواء للتسخين."},{"type":"text","text":"يحدث التغير الأديباتي عندما تتغير حالة حزمة الهواء دون تبادل حراري صافٍ مع محيطها خلال العملية المدروسة."},{"type":"text","text":"عند صعود حزمة هوائية تتمدد بسبب انخفاض الضغط المحيط، فينخفض مقدار طاقتها الداخلية ودرجة حرارتها."},{"type":"text","text":"عند هبوط الحزمة تنضغط بفعل ازدياد الضغط، فترتفع درجة حرارتها الأديباتية."},{"type":"text","text":"معدل التناقص الحراري الأديباتي الجاف يقارب 9.8 درجات مئوية لكل كيلومتر في ظروف مرجعية، وليس معدل تغير الحرارة البيئية."},{"type":"text","text":"بعد بلوغ الإشباع يبدأ التكاثف، وتحرر الحرارة الكامنة فتقل سرعة تبريد الحزمة مقارنة بالحالة الجافة."},{"type":"text","text":"المعدل الأديباتي المشبع متغير ويتأثر بدرجة الحرارة والضغط وكمية بخار الماء، لذلك لا يستخدم كقيمة ثابتة دقيقة في كل الحالات."},{"type":"text","text":"الحرارة الكامنة طاقة تنتقل أثناء تغير حالة الماء دون أن تقابلها زيادة مباشرة في درجة الحرارة عند ضغط ثابت تقريباً."},{"type":"text","text":"مثال: عند رفع حزمة رطبة إلى مستوى التكاثف، يبدأ بخار الماء بالتكاثف وتؤثر الحرارة الكامنة في مسار حرارتها."},{"type":"callout","text":"خلاصة: التحولات الأديباتية والحرارة الكامنة أساس تفسير السحب والحمل الحراري والاستقرار الجوي."}]}',550,55,'["تعريف المتغيرات الحرارية الأساسية","شرح التبريد والتسخين الأديباتي","التمييز بين الهواء الجاف والهواء المشبع"]','الحرارة والرطوبة والتحولات الأديباتية'),
('atmospheric-stability-and-convection','الاستقرار الجوي والحمل الحراري','مقارنة المعدلات الحرارية البيئية والأديباتية وتطور الحزم الهوائية والحمل.','{"blocks":[{"type":"text","text":"يعبر الاستقرار الجوي عن ميل الغلاف الجوي إلى مقاومة الإزاحة الرأسية أو تعزيزها، ويحدد تطور الحمل والسحب."},{"type":"text","text":"يقارن تقييم الاستقرار بين معدل التناقص الحراري البيئي ومعدلي التناقص الأديباتيين الجاف والمشبع."},{"type":"text","text":"يكون الجو مستقراً مطلقاً عندما يكون معدل التناقص البيئي أقل من المعدل المشبع، فتكون الحزمة المزاحة أبرد نسبياً من محيطها بعد الإشباع."},{"type":"text","text":"يكون الجو غير مستقر مطلقاً عندما يتجاوز معدل التناقص البيئي المعدل الجاف، فتكون الحزمة الصاعدة أدفأ من البيئة وفق المقارنة المثالية."},{"type":"text","text":"يظهر عدم الاستقرار الشرطي عندما يكون المعدل البيئي بين المعدلين المشبع والجاف، ويتوقف سلوك الحزمة على بلوغ الإشباع."},{"type":"text","text":"الانقلاب الحراري حالة تزداد فيها الحرارة مع الارتفاع ضمن طبقة، وغالباً تحد من الخلط الرأسي."},{"type":"text","text":"يحدث الحمل الحراري عندما تنشأ فروق في الطفو والكثافة تدفع الهواء إلى الحركة الرأسية، ويتأثر بالتسخين السطحي والرطوبة والقص."},{"type":"text","text":"يمثل مستوى التكاثف الحملي LCL الارتفاع التقريبي الذي تصل عنده الحزمة الصاعدة إلى الإشباع في ظروف الرفع الجاف الأولي."},{"type":"text","text":"تقيس CAPE طاقة الطفو المتاحة للحزمة ضمن طبقة موجبة الطفو، وتعتمد قيمتها على اختيار الحزمة والملف الرأسي."},{"type":"text","text":"تقيس CIN مقدار الطاقة السالبة التي تعيق بدء الصعود الحراري، وقد تتطلب الحالة آلية رفع لتجاوزها."},{"type":"text","text":"مثال: قد تتوفر CAPE كبيرة لكن تبقى السحب الحملية محدودة إذا كان الكبح قويّاً ولم توجد آلية رفع كافية."},{"type":"callout","text":"خلاصة: لا يفسر مؤشر واحد العواصف؛ يجب دمج الاستقرار والرطوبة والرفع والقص والسياق السينوبتيكي."}]}',560,60,'["تعريف الاستقرار المطلق والشرطي","تفسير الانقلاب الحراري والحمل","فهم دور CAPE وCIN"]','الحرارة والرطوبة والتحولات الأديباتية'),
('cloud-microphysics-and-precipitation','فيزياء السحب وعمليات الهطول','التكاثف ونوى السحب ونمو القطرات والبلورات ومسارات الهطول.','{"blocks":[{"type":"text","text":"تتكون السحب عندما يصل الهواء إلى الإشباع ويحدث التكاثف أو الترسب على جسيمات دقيقة تعمل نوى للتكاثف أو التجمد."},{"type":"text","text":"لا يعني بلوغ رطوبة نسبية 100 بالمئة وحده تشكل سحابة مرئية؛ إذ تؤثر وفرة النوى ودرجة الحرارة والحركة الرأسية."},{"type":"text","text":"تنمو قطرات السحب الصغيرة عبر تصادمها واندماجها، وتصبح قطرات أكبر قادرة على السقوط إذا تجاوزت أحجاماً مناسبة."},{"type":"text","text":"في السحب الدافئة تسهم عمليتا التصادم والالتحام في نمو قطرات المطر."},{"type":"text","text":"في السحب الباردة توجد بلورات جليدية وقطرات ماء فائقة التبريد، وقد ينمو الجليد على حساب بخار الماء والقطرات."},{"type":"text","text":"تصف عملية بيرجيرون-فيندايزن نمو البلورات الجليدية في بيئة مختلطة الطور بسبب اختلاف ضغط البخار المشبع فوق الماء والجليد."},{"type":"text","text":"قد تنمو البلورات عبر الترسب المباشر أو التجمد أو التراكم، ثم تتجمع لتشكل رقائق ثلجية أو حبيبات جليدية."},{"type":"text","text":"تختلف أشكال الهطول عند السطح وفق الملف الحراري الرأسي، وقد يتحول الثلج إلى مطر أو مطر متجمد أو خليط بحسب طبقات الذوبان وإعادة التجمد."},{"type":"text","text":"تعتمد كفاءة الهطول على محتوى الماء السحابي وعمق السحابة والتيارات الرأسية والرياح والعمليات الدقيقة."},{"type":"text","text":"قد لا يصل الهطول إلى الأرض إذا تبخر أو تسامى أثناء سقوطه عبر طبقة جافة، وينتج عن ذلك virga."},{"type":"text","text":"مثال: تفسير تساقط الثلج يتطلب فحص درجة الحرارة من السحابة إلى السطح، وليس درجة حرارة المحطة السطحية وحدها."},{"type":"callout","text":"خلاصة: فيزياء السحب تربط العمليات المجهرية بتوزيع الهطول وشدته ونوعه."}]}',570,60,'["شرح تشكل السحب والتكاثف","تمييز عمليات نمو الهطول","فهم دور الجليد والقطرات فائقة التبريد"]','السحب والهطول والأنظمة الجوية'),
('air-masses-fronts-and-cyclones','الكتل الهوائية والجبهات والمنخفضات','خصائص الكتل الهوائية وتكوين الجبهات وتطور المنخفضات خارج المدارية.','{"blocks":[{"type":"text","text":"الكتلة الهوائية حجم واسع من الهواء تتقارب خصائصه الحرارية والرطوبية أفقياً نسبياً بسبب بقائه فوق منطقة مصدر مدة كافية."},{"type":"text","text":"تصنف الكتل الهوائية وفق طبيعة منطقة المصدر إلى قارية أو بحرية، ووفق المجال الحراري إلى قطبية أو مدارية وغيرها."},{"type":"text","text":"تكتسب الكتلة الهوائية خصائصها من السطح الذي تعلوه، ثم تتغير تدريجياً أثناء انتقالها فوق مناطق مختلفة."},{"type":"text","text":"الجبهة منطقة انتقالية تفصل بين كتلتين هوائيتين مختلفتين في الكثافة والحرارة والرطوبة."},{"type":"text","text":"الجبهة الباردة تتقدم فيها كتلة أبرد نسبياً وتزيح الهواء الأدفأ، وقد يصاحبها رفع وسحب وهطول متفاوت."},{"type":"text","text":"الجبهة الدافئة تتقدم فيها كتلة أدفأ فوق هواء أبرد، ويكون الميل الجبهي عادة لطيفاً نسبياً مع نطاق سحب واسع."},{"type":"text","text":"الجبهة الثابتة منطقة لا يتحرك فيها الحد الفاصل بوضوح، بينما تتكون الجبهة المسدودة عندما تلحق الجبهة الباردة بالدافئة."},{"type":"text","text":"تتطور المنخفضات خارج المدارية غالباً ضمن مناطق التباين الحراري والقص، وتتأثر بديناميكية الطبقات العليا."},{"type":"text","text":"يوضح نموذج النرويج التقليدي مراحل تطور المنخفض من موجة جبهية إلى نضج ثم انسداد، لكنه ليس وصفاً وحيداً لكل الحالات."},{"type":"text","text":"يساعد توافق المنخفض السطحي مع الأخدود العلوي ومناطق الرفع على تقييم تطوره، مع فحص الرطوبة والاستقرار."},{"type":"text","text":"مثال: عند مرور جبهة باردة راقب تغير اتجاه الرياح والضغط والحرارة ونوع السحب والهطول قبل الجبهة وبعدها."},{"type":"callout","text":"خلاصة: فهم الكتل والجبهات يربط خرائط السطح بالتركيب الحراري والحركة في الطبقات العليا."}]}',580,60,'["تصنيف الكتل الهوائية","شرح الجبهات الهوائية","تفسير تطور المنخفضات خارج المدارية"]','السحب والهطول والأنظمة الجوية'),
('mesoscale-convective-systems','العواصف الحملية والأنظمة متوسطة المقياس','تنظيم الحمل العميق والعواصف الرعدية والخلايا والأنظمة الحملية واسعة الامتداد.','{"blocks":[{"type":"text","text":"تنتج العواصف الحملية عن صعود هواء رطب غير مستقر، وتحتاج عادة إلى رطوبة ورفع وبيئة تسمح باستمرار التيارات الصاعدة."},{"type":"text","text":"تمر الخلية الرعدية المفردة بمراحل نمو ونضج واضمحلال، وتتداخل التيارات الصاعدة والهابطة في المرحلة الناضجة."},{"type":"text","text":"تنتج السحابة الركامية المزنية عن نمو رأسي عميق، وقد يصاحبها برق ورعد وهطول غزير وبرد وهبات رياح."},{"type":"text","text":"يساعد القص الرأسي على فصل التيار الصاعد عن الهابط، وقد يطيل عمر العاصفة وينظم بنيتها."},{"type":"text","text":"تتكون العواصف متعددة الخلايا من خلايا في مراحل مختلفة، وقد تتجدد على طول حد هبات أو منطقة تقارب."},{"type":"text","text":"الخطوط الحملية أنظمة طويلة نسبياً من العواصف، وقد تنتج هبات رياح قوية وأمطاراً غزيرة."},{"type":"text","text":"النظام الحملي متوسط المقياس MCS تجمع من العواصف المنظمة يمتد مكانياً وزمانياً أكثر من الخلية المفردة."},{"type":"text","text":"قد تتطور بعض الأنظمة الحملية إلى منظومات ذات منطقة هطول واسعة ودوران متوسط المقياس وفق البيئة والديناميكية."},{"type":"text","text":"تؤثر حدود هبات الرياح والتقارب السطحي والتضاريس والتسخين النهاري في مواقع بدء الحمل وتجدد الخلايا."},{"type":"text","text":"تستخدم الرادارات والأقمار الصناعية والبرق وبيانات المحطات معاً لمراقبة تطور الأنظمة الحملية."},{"type":"text","text":"مثال: عند متابعة خط عواصف، افحص اتجاه الحركة وتجدد الخلايا وحد الهبات والبيئة الرطوبية والقص، ولا تعتمد على صدى الرادار وحده."},{"type":"callout","text":"خلاصة: التنظيم متوسط المقياس يفسر كيف تتحول الخلايا المنفردة إلى أنظمة مؤثرة واسعة النطاق."}]}',590,60,'["تمييز الخلية الرعدية ومراحلها","شرح تنظيم العواصف بالقص","التعرف إلى الأنظمة الحملية متوسطة المقياس"]','السحب والهطول والأنظمة الجوية'),
('numerical-weather-prediction-fundamentals','مبادئ التنبؤ العددي بالطقس','أسس النماذج العددية ومعادلات الحركة والشبكات والحلول التقريبية.','{"blocks":[{"type":"text","text":"التنبؤ العددي بالطقس يستخدم معادلات فيزيائية تصف حركة الهواء والطاقة والرطوبة لتقدير الحالة الجوية المستقبلية."},{"type":"text","text":"تبدأ عملية التنبؤ بتمثيل الحالة الابتدائية للغلاف الجوي باستخدام الرصد والتحليل، ثم تكامل المعادلات إلى الأمام زمنياً."},{"type":"text","text":"تشمل المعادلات الأساسية حفظ الكتلة والزخم والطاقة والماء، إضافة إلى علاقات الحالة والتغيرات الطورية."},{"type":"text","text":"تصف معادلات الحركة تأثير تدرج الضغط والجاذبية وكوريوليس والاحتكاك والنقل بالحركة."},{"type":"text","text":"تربط معادلة الاستمرارية تغير الكثافة بتقارب وتباعد تدفق الكتلة، وتختلف صياغتها باختلاف الإحداثيات والتقريبات."},{"type":"text","text":"تصف معادلة الطاقة تغير الحالة الحرارية بفعل النقل والإشعاع والحرارة الكامنة والتبادل السطحي."},{"type":"text","text":"تقسم الشبكة العددية المجال المكاني إلى نقاط أو خلايا تحسب عندها المتغيرات، وقد تكون شبكات منتظمة أو متداخلة أو غير منظمة."},{"type":"text","text":"تحدد الخطوة الزمنية مقدار تقدم النموذج في كل عملية حسابية، وترتبط بالاستقرار العددي ودقة الحل."},{"type":"text","text":"تستخدم مخططات عددية لتقريب المشتقات والتدفقات، وتوازن بين الدقة والاستقرار والكلفة الحسابية."},{"type":"text","text":"تحتاج الظواهر الأصغر من دقة الشبكة إلى تمثيل تقريبي عبر مخططات فيزيائية مثل الحمل والسحب والاضطراب."},{"type":"text","text":"مثال: زيادة دقة الشبكة قد تحسن تمثيل بعض التفاصيل، لكنها ترفع كلفة الحساب ولا تضمن وحدها تنبؤاً أدق."},{"type":"callout","text":"خلاصة: النموذج العددي منظومة مترابطة من معادلات وحالة ابتدائية وشبكة ومخططات فيزيائية وعددية."}]}',600,65,'["شرح فكرة النموذج العددي","التعرف إلى معادلات الغلاف الجوي","فهم الشبكات والخطوات الزمنية"]','أساسيات التنبؤ العددي'),
('data-assimilation-in-nwp','استيعاب البيانات وتهيئة الحالة الابتدائية','دمج الرصد مع خلفية النموذج لإنتاج تحليل جوي متوازن.','{"blocks":[{"type":"text","text":"استيعاب البيانات عملية دمج المشاهدات الجوية مع توقع خلفي من نموذج لإنتاج أفضل تقدير ممكن للحالة الابتدائية."},{"type":"text","text":"الخلفية أو التخمين الأولي غالباً توقع قصير المدى من دورة النموذج السابقة، ويحتوي على معلومات ديناميكية متسقة."},{"type":"text","text":"تشمل المشاهدات بيانات المحطات والراديوسوند والطائرات والسفن والرادار والأقمار الصناعية، ولكل منها خصائص خطأ وتمثيل مختلفة."},{"type":"text","text":"يوازن التحليل بين قربه من المشاهدات واتساقه مع الخلفية وفق تقديرات أخطاء الرصد والخلفية."},{"type":"text","text":"تستخدم طرق الاستيعاب المتغيرية دالة كلفة تجمع فروق التحليل عن الخلفية وعن المشاهدات."},{"type":"text","text":"يستفيد الاستيعاب رباعي الأبعاد من توقيت المشاهدات خلال نافذة زمنية لربطها بتطور الحالة الجوية."},{"type":"text","text":"تستخدم مرشحات كالمان أو مقارباتها ensemble في بعض الأنظمة لتقدير تطور أخطاء الحالة."},{"type":"text","text":"تتطلب بيانات الأقمار الصناعية معالجة مسبقة واختيار قنوات ومعلومات مساعدة وتمثيل دالة الرصد."},{"type":"text","text":"تؤثر مراقبة الجودة في استبعاد القياسات الشاذة أو تقليل وزنها قبل الاستيعاب."},{"type":"text","text":"قد تؤدي أخطاء الموقع أو التوقيت أو المعايرة أو التمثيل إلى إضعاف التحليل إذا لم تكتشف."},{"type":"text","text":"مثال: مقارنة رصد راديوسوند بخلفية النموذج تساعد على تحديد الابتكار، ثم يحدد نظام الاستيعاب وزنه وفق عدم اليقين."},{"type":"callout","text":"خلاصة: جودة التنبؤ تبدأ من جودة التحليل الابتدائي، وليس من معادلات النموذج وحدها."}]}',610,60,'["شرح مفهوم الاستيعاب","تمييز الرصد والخلفية والتحليل","التعرف إلى طرق الاستيعاب"]','أساسيات التنبؤ العددي'),
('nwp-grids-physics-boundary-conditions','شبكات النماذج ومخططات الفيزياء والشروط الحدية','اختيارات الشبكة والإحداثيات والتمثيل الفيزيائي والشروط الابتدائية والحدية.','{"blocks":[{"type":"text","text":"تحدد الشبكة الأفقية والرأسية كيف يمثل النموذج المجال الجوي، وتؤثر دقتها في الظواهر التي يستطيع حلها مباشرة."},{"type":"text","text":"تشير الدقة الأفقية إلى المسافة بين نقاط الشبكة أو حجم الخلية، بينما تصف الدقة الرأسية توزيع المستويات في الارتفاع أو الضغط."},{"type":"text","text":"تستخدم النماذج إحداثيات رأسية مختلفة مثل الإحداثيات الضغطية أو sigma أو hybrid بحسب التصميم."},{"type":"text","text":"تمثل مخططات السطح التبادل بين الغلاف الجوي والتربة والغطاء النباتي والماء، وتشمل التدفقات الحرارية والرطوبية والزخم."},{"type":"text","text":"تعالج مخططات الإشعاع انتقال الطاقة الشمسية والأرضية وامتصاصها وتشتتها بواسطة الغازات والسحب والهباء."},{"type":"text","text":"تمثل مخططات السحب والهطول تكوين القطرات والبلورات ونموها وسقوطها، وتؤثر في توزيع الهطول والتسخين الكامن."},{"type":"text","text":"تصف مخططات الاضطراب والحمل آثار الحركات الأصغر من الشبكة على النقل الرأسي والأفقي."},{"type":"text","text":"تستخدم الشروط الحدية الجانبية في النماذج الإقليمية لتزويد أطراف المجال بالمعلومات القادمة من نموذج أكبر."},{"type":"text","text":"تحتاج النماذج إلى شروط سطحية مناسبة مثل حرارة سطح البحر ورطوبة التربة والغطاء الأرضي."},{"type":"text","text":"قد تظهر أخطاء عند عدم اتساق الشبكة أو الفيزياء أو الشروط الحدية، حتى لو كانت المدخلات الأولية جيدة."},{"type":"text","text":"مثال: تشغيل نموذج إقليمي بدقة أعلى لا يعالج تلقائياً أخطاء الشروط الحدية أو تمثيل السحب والتضاريس."},{"type":"callout","text":"خلاصة: أداء النموذج نتيجة تفاعل الشبكة والفيزياء والشروط الحدية والتهيئة، وليس الدقة الأفقية وحدها."}]}',620,65,'["تمييز الدقة الأفقية والرأسية","شرح مخططات الفيزياء","فهم الشروط الحدية"]','تصميم وتشغيل النماذج'),
('forecast-verification-methods','التحقق من التنبؤات ومقاييس الأداء','مقارنة التنبؤ بالمشاهدات وتقييم الانحياز والخطأ والمهارة.','{"blocks":[{"type":"text","text":"التحقق من التنبؤ يقارن القيم المتوقعة بالمشاهدات المرجعية لتقييم الجودة وتحديد جوانب القوة والقصور."},{"type":"text","text":"يجب أن تكون المشاهدات المرجعية مناسبة مكانياً وزمانياً للمتغير المتوقع، مع مراعاة أخطاء القياس والتمثيل."},{"type":"text","text":"يعرف الخطأ بأنه الفرق بين التنبؤ والمشاهدة وفق اصطلاح إشارة معلن وثابت."},{"type":"text","text":"يقيس متوسط الخطأ أو الانحياز الاتجاه العام للمبالغة أو التقليل، وقد يخفي أخطاء موجبة وسالبة متعاكسة."},{"type":"text","text":"يقيس متوسط الخطأ المطلق MAE متوسط مقدار الأخطاء دون إلغاء الإشارات."},{"type":"text","text":"يعطي الجذر التربيعي لمتوسط مربع الخطأ RMSE وزناً أكبر للأخطاء الكبيرة مقارنة بالأخطاء الصغيرة."},{"type":"text","text":"يستخدم الارتباط لوصف التوافق في التغيرات، لكنه لا يقيس وحده دقة القيم أو غياب الانحياز."},{"type":"text","text":"تستخدم مقاييس الفئات مثل POD وFAR وCSI لتقييم أحداث نعم أو لا، مثل تجاوز عتبة هطول محددة."},{"type":"text","text":"يجب تحديد العتبة والمنطقة والفترة ومهلة التنبؤ قبل مقارنة نتائج نماذج مختلفة."},{"type":"text","text":"تساعد الرسوم مثل مخططات الانتشار ومخططات الانحياز وتوزيع الأخطاء في كشف الأنماط المكانية والزمنية."},{"type":"text","text":"مثال: نموذج ذو RMSE أقل قد يكون أفضل في مجموعة الحالات المختبرة، لكن يجب فحص الانحياز والتوزيع والفئات الشديدة أيضاً."},{"type":"callout","text":"خلاصة: التحقق المتوازن يستخدم عدة مقاييس ويعلن حدود البيانات المرجعية والعينة المختبرة."}]}',630,55,'["تعريف التحقق من التنبؤ","حساب مقاييس الخطأ الأساسية","تفسير الانحياز والمهارة"]','تقييم التنبؤ وعدم اليقين'),
('ensemble-forecasting-and-uncertainty','التنبؤ التجميعي وتقدير عدم اليقين','المجموعات العددية والانتشار والاحتمالات والمهارة الاحتمالية.','{"blocks":[{"type":"text","text":"ينتج التنبؤ التجميعي مجموعة محاكاة من خلال تغيير الشروط الابتدائية أو النمذجة أو كليهما لتقدير نطاق الحالات الممكنة."},{"type":"text","text":"تعكس الفروق بين أعضاء المجموعة حساسية التنبؤ لعدم اليقين في الحالة الأولية والتمثيل الفيزيائي."},{"type":"text","text":"لا يمثل انتشار المجموعة كل مصادر عدم اليقين بالضرورة، وقد تكون المجموعة منحازة أو ناقصة التشتت أو مفرطة التشتت."},{"type":"text","text":"يستخدم المتوسط والوسيط لتلخيص مركز المجموعة، بينما يصف الانحراف المعياري أو المدى انتشار الأعضاء."},{"type":"text","text":"يمكن تحويل أعضاء المجموعة إلى احتمالات تجاوز عتبة، مثل احتمال هطول يتجاوز قيمة محددة خلال فترة معلومة."},{"type":"text","text":"يجب أن يحدد الاحتمال الحدث والعتبة والمكان والفترة بوضوح حتى يكون قابلاً للتفسير."},{"type":"text","text":"تستخدم مخططات السباغيتي لعرض مسارات أو خطوط متوقعة متعددة، وتفيد في تصور اختلاف السيناريوهات."},{"type":"text","text":"تساعد خرائط الاحتمال على تمييز المناطق ذات فرص أعلى للحدث، لكنها لا تعني ضمان وقوعه."},{"type":"text","text":"يقيس مخطط الموثوقية مدى توافق الأحداث المتحققة مع الاحتمالات المتوقعة عبر فئات احتمالية."},{"type":"text","text":"تستخدم مقاييس مثل Brier Score لتقييم جودة التنبؤات الاحتمالية للأحداث الثنائية، مع فصل الموثوقية والتمييز وعدم اليقين في التحليل."},{"type":"text","text":"مثال: احتمال 70 بالمئة يعني أن أحداثاً مماثلة متوقعة بهذا الاحتمال ينبغي أن تتحقق في نحو 70 بالمئة من الحالات على عينة كبيرة ومعايرة مناسبة."},{"type":"callout","text":"خلاصة: التنبؤ التجميعي يحول التوقع من قيمة وحيدة إلى نطاق واحتمالات تساعد على اتخاذ القرار."}]}',640,60,'["شرح التنبؤ التجميعي","قراءة الانتشار والاحتمالات","فهم التحقق الاحتمالي"]','تقييم التنبؤ وعدم اليقين'),
('forecast-communication-and-warning-basics','صياغة التوقعات الجوية والتواصل بشأن عدم اليقين','تحويل مخرجات النماذج إلى توقعات مفهومة ورسائل احتمالية ومسؤولة.','{"blocks":[{"type":"text","text":"صياغة التوقع الجوي تحول التحليل والبيانات إلى رسالة زمنية ومكانية واضحة للمستخدم."},{"type":"text","text":"يجب أن يحدد التوقع المنطقة والفترة والمتغيرات المتوقعة، مثل الحرارة والرياح والهطول والسحب."},{"type":"text","text":"ينبغي التمييز بين وصف الحالة المتوقعة ودرجة الثقة بها، فلا تعرض نتيجة النموذج كحقيقة مؤكدة."},{"type":"text","text":"يستخدم الاحتمال عندما يكون الحدث معرفاً بوضوح، مثل احتمال تجاوز كمية هطول خلال فترة محددة."},{"type":"text","text":"عدم اليقين قد ينتج من الحالة الابتدائية أو النموذج أو العمليات الفيزيائية أو محدودية الرصد."},{"type":"text","text":"تتطلب التحذيرات ربط احتمال الظاهرة بشدتها ومدتها ومكانها والتعرض لها وقابلية التأثر."},{"type":"text","text":"الخطر لا يساوي الاحتمال وحده؛ فالأثر المتوقع يعتمد أيضاً على شدة الحدث والتعرض والهشاشة."},{"type":"text","text":"تستخدم لغة مباشرة وتجنب المصطلحات الفنية غير المشروحة عند مخاطبة الجمهور العام."},{"type":"text","text":"يجب تحديث الرسائل عند تغير الأدلة، مع توضيح وقت إصدار التحديث والفترة التي يغطيها."},{"type":"text","text":"من الممارسات الجيدة بيان ما هو معروف وما يزال غير مؤكد وما الإجراء الوقائي الرسمي المعتمد."},{"type":"text","text":"مثال: بدلاً من قول أمطار مؤكدة، حدد فرصة الهطول ومجاله الزمني ومناطقه المحتملة ومستوى الثقة."},{"type":"callout","text":"خلاصة: التواصل الجيد يحافظ على الدقة العلمية ويجعل التوقع مفهوماً وقابلاً للاستخدام."}]}',650,50,'["بناء ملخص توقع جوي","التعبير عن عدم اليقين","التمييز بين الخطر والاحتمال والأثر"]','تقييم التنبؤ وعدم اليقين'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'الحرارة والرطوبة والتحولات الأديباتية' then u1.id when 'السحب والهطول والأنظمة الجوية' then u2.id when 'أساسيات التنبؤ العددي' then u3.id when 'تصميم وتشغيل النماذج' then u4.id when 'تقييم التنبؤ وعدم اليقين' then u5.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الديناميكا الجوية والفيزياء الجوية والتنبؤ العددي',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;